# Phase 02: a customer rates a resolved ticket

**Makes work:** `portal.rateTicket(store, customer, id, score)` stores one rating on a resolved ticket of the customer's organisation. **Check:** `node --test test/csat.test.js`. **Blocked by:** 01. Mode: ACT, but tenant scoping is a hot path, so phase 05 reviews it.

Context: `src/portal.js:6-9,24-30` (`getMyTicket`, `reply`), `src/store.js:19-22`, `src/tickets.js:8-20`.

## Steps
- [ ] 1. Failing tests. Create `test/csat.test.js`:
  ```js
  'use strict';
  const test = require('node:test');
  const assert = require('node:assert/strict');
  const { createStore } = require('../src/store');
  const { resolveTicket, STATUS } = require('../src/tickets');
  const portal = require('../src/portal');
  const { closeResolved } = require('../src/jobs/close-resolved');

  const DAY = 24 * 60 * 60 * 1000;
  const at = (days) => new Date(Date.UTC(2026, 0, 1) + days * DAY);
  const acme = { id: 7, orgId: 1 };
  const globex = { id: 9, orgId: 2 };

  function resolved(store, { owner = 41 } = {}) {
    const t = portal.openTicket(store, acme, { subject: 'Printer', body: 'x' });
    if (owner) store.updateTicket(t.id, { owner_id: owner });
    resolveTicket(store, t.id, 41, { now: at(1) });
    return t;
  }

  test('a customer rates a resolved ticket of their organisation', () => {
    const store = createStore();
    const t = resolved(store);
    const r = portal.rateTicket(store, acme, t.id, 4, { now: at(2) });
    assert.equal(r.rating_score, 4);
    assert.equal(r.rated_at, at(2).toISOString());
    assert.equal(store.getTicket(t.id).rating_score, 4);
  });

  test('a score that is not a whole number from 1 to 5 is refused', () => {
    const store = createStore();
    const t = resolved(store);
    for (const bad of [0, 6, 3.5, '4', NaN, null, undefined]) {
      assert.throws(() => portal.rateTicket(store, acme, t.id, bad), /whole number from 1 to 5/);
    }
    assert.equal(store.getTicket(t.id).rating_score, null);
  });

  test('an open, pending or closed ticket cannot be rated', () => {
    const store = createStore();
    const t = resolved(store);
    store.updateTicket(t.id, { status: STATUS.OPEN });
    assert.throws(() => portal.rateTicket(store, acme, t.id, 4), /cannot rate a open ticket/);
    store.updateTicket(t.id, { status: STATUS.PENDING });
    assert.throws(() => portal.rateTicket(store, acme, t.id, 4), /cannot rate a pending ticket/);
    store.updateTicket(t.id, { status: STATUS.RESOLVED, resolved_at: at(1).toISOString() });
    closeResolved(store, { now: at(5) });
    assert.throws(() => portal.rateTicket(store, acme, t.id, 4), /cannot rate a closed ticket/);
  });

  test('a second rating is refused and the first stays', () => {
    const store = createStore();
    const t = resolved(store);
    portal.rateTicket(store, acme, t.id, 4, { now: at(2) });
    assert.throws(() => portal.rateTicket(store, acme, t.id, 1, { now: at(3) }), /already rated/);
    const after = store.getTicket(t.id);
    assert.equal(after.rating_score, 4);
    assert.equal(after.rated_at, at(2).toISOString());
  });

  test('another organisation gets the answer for a ticket that does not exist', () => {
    const store = createStore();
    const t = resolved(store);
    assert.equal(portal.rateTicket(store, globex, t.id, 4), null);
    assert.equal(portal.rateTicket(store, acme, 999, 4), null);
    assert.equal(store.getTicket(t.id).rating_score, null);
  });
  ```
  Run `node --test test/csat.test.js`. Evidence: all five fail with `portal.rateTicket is not a function`.
- [ ] 2. In `src/tickets.js` add `rating_score: null,` and `rated_at: null,` after `closed_at: null,` (line 18) in `createTicket`.
- [ ] 3. In `src/store.js` add after `updateTicket` (line 21):
  ```js
    // Sets the rating only if the ticket has none; returns null when it already has one. Production does this as one
    // conditional UPDATE (... WHERE id = $1 AND rating_score IS NULL) so two requests cannot both win.
    rateTicketOnce(id, { score, at }) {
      const t = tickets.get(id);
      if (!t) throw new Error(`no ticket ${id}`);
      if (t.rating_score != null) return null;
      t.rating_score = score;
      t.rated_at = at;
      return { ...t };
    },
  ```
- [ ] 4. In `src/portal.js` add before `module.exports`, and add `rateTicket` to the exports:
  ```js
  // The customer rates a resolved ticket, once. Another organisation's ticket looks like one that does not exist.
  function rateTicket(store, customer, id, score, { now = new Date() } = {}) {
    const t = getMyTicket(store, customer, id);
    if (!t) return null;
    if (!Number.isInteger(score) || score < 1 || score > 5) throw new Error('the score must be a whole number from 1 to 5');
    if (t.status !== STATUS.RESOLVED) throw new Error(`cannot rate a ${t.status} ticket`);
    if (!store.rateTicketOnce(id, { score, at: now.toISOString() })) throw new Error('this ticket is already rated');
    return getMyTicket(store, customer, id);
  }
  ```
  Evidence: `node --test` fully green (the new file plus the old ones), output pasted.
- [ ] 5. Negative control: temporarily change `t.org_id !== customer.orgId` in `getMyTicket` to `false`, run `node --test test/csat.test.js`, show the other-organisation test fails, revert, show green. Evidence: both outputs.
- [ ] 6. Commit `feat: customers rate a resolved ticket`.

## Exit criteria
The acceptance criteria for requirements 1-3 pass; negative control shown.

## Risks
Old rows without `rating_score` (undefined): `!= null` treats them as unrated. Concurrent double rating: covered by `rateTicketOnce`; the Postgres version must keep it conditional (plan Question 2).

