    assert.equal(portal.rateTicket(store, acme, t.id, 1).rating_score, 1);
    assert.deepEqual(drain(), []);
  });

  test('a refused second rating queues no second email', () => {
    const store = createStore();
    drain();
    const t = resolved(store);
    portal.rateTicket(store, acme, t.id, 1);
    assert.throws(() => portal.rateTicket(store, acme, t.id, 1), /already rated/);
    assert.equal(drain().length, 1);
  });
  ```
  Run `node --test test/csat.test.js`. Evidence: the first fails (`[]` instead of one email); the other two may already pass, which is stated in the output paste.
- [ ] 2. In `src/portal.js` add `const { notifyAgent } = require('./notify');` under the existing require, and in `rateTicket` replace the `rateTicketOnce` line with:
  ```js
    const rated = store.rateTicketOnce(id, { score, at: now.toISOString() });
    if (!rated) throw new Error('this ticket is already rated');
    if (score <= 2 && rated.owner_id) notifyAgent(store, rated.owner_id, { type: 'ticket_rated_low', ticketId: id, score });
  ```
  Evidence: `node --test` fully green, pasted.
- [ ] 3. Commit `feat: email the owner on a low rating`.

## Exit criteria
"Score 2 queues one email, score 3 none" passes; unassigned does not throw.

## Risks
The email is queued after the rating is stored; if `notifyAgent` threw, the rating would stay and the customer would see an error. The only throw is a missing agent, which the guard excludes.

