# Phase 04: weekly summary per agent

**Makes work:** a nightly job saves, per owner, the number of ratings and the average over the past seven days. **Check:** `node --test test/weekly-csat-summary.test.js`. **Blocked by:** 02. Mode: ACT.

Context: job shape in `src/jobs/close-resolved.js` (function taking `store` and `{ now }`); store interface `src/store.js`.

## Steps
- [ ] 1. Failing tests. Create `test/weekly-csat-summary.test.js`:
  ```js
  'use strict';
  const test = require('node:test');
  const assert = require('node:assert/strict');
  const { createStore } = require('../src/store');
  const { resolveTicket } = require('../src/tickets');
  const portal = require('../src/portal');
  const { weeklyCsatSummary } = require('../src/jobs/weekly-csat-summary');

  const DAY = 24 * 60 * 60 * 1000;
  const at = (days) => new Date(Date.UTC(2026, 0, 1) + days * DAY);
  const acme = { id: 7, orgId: 1 };

  function rated(store, owner, score, day) {
    const t = portal.openTicket(store, acme, { subject: 'Printer', body: 'x' });
    if (owner) store.updateTicket(t.id, { owner_id: owner });
    resolveTicket(store, t.id, 41, { now: at(day) });
    portal.rateTicket(store, acme, t.id, score, { now: at(day) });
  }

  test('ratings 5, 4 and 1 in seven days average 3.33; one eight days old is not counted', () => {
    const store = createStore();
    rated(store, 41, 5, 3);
    rated(store, 41, 4, 5);
    rated(store, 41, 1, 8);
    rated(store, 41, 2, 0);
    rated(store, 42, 3, 4);
    rated(store, null, 1, 4);
    weeklyCsatSummary(store, { now: at(8) });
    assert.deepEqual(store.listSummaries(), [
      { agent_id: 41, week_ending: '2026-01-09', ratings: 3, average: 3.33 },
      { agent_id: 42, week_ending: '2026-01-09', ratings: 1, average: 3 },
    ]);
  });

  test('running the job twice on one day leaves one row per agent', () => {
    const store = createStore();
    rated(store, 41, 5, 3);
    weeklyCsatSummary(store, { now: at(8) });
    weeklyCsatSummary(store, { now: at(8) });
    assert.equal(store.listSummaries().length, 1);
  });
  ```
  Run it. Evidence: fails with `Cannot find module '../src/jobs/weekly-csat-summary'`.
- [ ] 2. In `src/store.js` add `const summaries = new Map();` after `const messages = new Map();`, and these methods after `deleteMessages`:
  ```js
    // One row per agent per week_ending; saving again replaces it, so a rerun does not duplicate.
    saveSummary(row) {
      summaries.set(`${row.agent_id}:${row.week_ending}`, { ...row });
    },
    listSummaries() {
      return [...summaries.values()].map((s) => ({ ...s }));
    },
  ```
- [ ] 3. Create `src/jobs/weekly-csat-summary.js`:
  ```js
  'use strict';
  // Nightly. Per agent (the ticket's current owner): how many ratings their tickets got in the past seven days and the
  // average score. Tickets without an owner and agents without ratings get no row.
  const WINDOW_DAYS = 7;
  const DAY = 24 * 60 * 60 * 1000;

  function weeklyCsatSummary(store, { now = new Date() } = {}) {
    const from = now.getTime() - WINDOW_DAYS * DAY;
    const byAgent = new Map();
    for (const t of store.listTickets()) {
      if (t.rating_score == null || t.owner_id == null) continue;
      const rated = new Date(t.rated_at).getTime();
      if (rated < from || rated > now.getTime()) continue;
      const scores = byAgent.get(t.owner_id) || [];
      scores.push(t.rating_score);
      byAgent.set(t.owner_id, scores);
    }
    const week_ending = now.toISOString().slice(0, 10);
    for (const [agent_id, scores] of byAgent) {
      const average = Math.round((scores.reduce((a, b) => a + b, 0) / scores.length) * 100) / 100;
      store.saveSummary({ agent_id, week_ending, ratings: scores.length, average });
    }
    return byAgent.size;
  }

  module.exports = { weeklyCsatSummary, WINDOW_DAYS };
  ```
  Evidence: `node --test` fully green, pasted.
- [ ] 4. Negative control: change `rated < from` to `rated < from - 2 * DAY`, run the file, show the eight-day-old rating makes the first test fail, revert, show green.
- [ ] 5. In `README.md` change "Three jobs run every night" to "Four" and add the line ``- `src/jobs/weekly-csat-summary.js` saves each agent's rating count and average for the past seven days.`` Evidence: `git diff README.md`.
- [ ] 6. Commit `feat: weekly rating summary per agent`.

## Exit criteria
The 5/4/1 example gives 3 ratings and 3.33; the eight-day-old rating is not counted; a rerun does not duplicate.

## Risks
A ticket reassigned after rating moves to the new owner's summary (accepted, Question 4). Rounding at .005 boundaries is cosmetic.

